// SI-generated: this file was generated by Claude Code (Anthropic, SI tool) and reviewed by the team.
//! EVA（艙外活動）模型：步行速度、時間、輻射劑量。全部是簡化假設，簡報時要說明。
//!
//! 步行速度：Tobler 健行函數的對稱版本 `v = v0 · exp(−3.5·tanθ)`，再依粗糙度減速
//! `÷ (1 + rough/rough_scale)`。平地 = v0；25° 約為 v0 的 20%。

use crate::grid::Grid;
use crate::par;

/// 步行速度（m/s）。
#[inline]
pub fn walk_speed(v0: f32, slope_deg: f32, rough_m: f32, rough_scale_m: f32) -> f32 {
    v0 * (-3.5 * slope_deg.to_radians().tan()).exp() / (1.0 + rough_m / rough_scale_m)
}

/// 每公尺所需秒數；危險格為 ∞。拿來跑 Dijkstra／A* 就得到「時間」。
pub fn seconds_per_m(
    slope: &Grid<f32>,
    rough: &Grid<f32>,
    hazard: &Grid<bool>,
    v0: f32,
    rough_scale_m: f32,
) -> Grid<f32> {
    let data = par::map_range(slope.data.len(), |k| {
        if hazard.data[k] {
            f32::INFINITY
        } else {
            1.0 / walk_speed(v0, slope.data[k], rough.data[k], rough_scale_m)
        }
    });
    Grid::from_vec(slope.w, slope.h, slope.cell_m, data)
}

/// 劑量（mSv）= 時間 × 地表劑量率。
#[inline]
pub fn dose_msv(minutes: f32, msv_per_day: f32) -> f32 {
    minutes * msv_per_day / 1440.0
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn flat_speed_is_v0_and_slope_slows() {
        assert!((walk_speed(1.0, 0.0, 0.0, 0.3) - 1.0).abs() < 1e-6);
        let mut prev = 1.0;
        for s in [5.0, 10.0, 15.0, 20.0, 25.0] {
            let v = walk_speed(1.0, s, 0.0, 0.3);
            assert!(v < prev);
            prev = v;
        }
        assert!(walk_speed(1.0, 0.0, 0.3, 0.3) < 0.51);
    }

    #[test]
    fn dose_one_day() {
        assert!((dose_msv(1440.0, 0.7) - 0.7).abs() < 1e-6);
    }
}
